import numpy as np
import pandas as pd
import pandas._testing as tm
from pandas.tseries.offsets import DateOffset

def apply_expr(expr_id):
    # Each case mirrors the report examples; we return either a value (stringified)
    # or an exception marker.
    try:
        if expr_id == 'dti_max_months1_days-31':
            dti = pd.DatetimeIndex([pd.Timestamp.max])
            res = dti + DateOffset(months=1, days=-31)
            return ('value', res)
        if expr_id == 'dti_max_years1_days-366':
            dti = pd.DatetimeIndex([pd.Timestamp.max])
            res = dti + DateOffset(years=1, days=-366)
            return ('value', res)
        if expr_id == 'dti_max_months2_days-62':
            dti = pd.DatetimeIndex([pd.Timestamp.max])
            res = dti + DateOffset(months=2, days=-62)
            return ('value', res)
        if expr_id == 'dti_max_months1_hours-745':
            dti = pd.DatetimeIndex([pd.Timestamp.max])
            res = dti + DateOffset(months=1, hours=-745)
            return ('value', res)
        if expr_id == 'dti_min_months-1_days32':
            dti = pd.DatetimeIndex([pd.Timestamp.min])
            res = dti + DateOffset(months=-1, days=32)
            return ('value', res)
        if expr_id == 'dti_max_months1_days-1':
            dti = pd.DatetimeIndex([pd.Timestamp.max])
            res = dti + DateOffset(months=1, days=-1)
            return ('value', res)
        if expr_id == 'dti_sec_unit_np_i64max':
            dti = pd.DatetimeIndex(np.array([np.iinfo(np.int64).max], dtype='M8[s]'))
            res = dti + DateOffset(months=1, days=-31)
            return ('value', res)
        if expr_id == 'dti_2000_01_31_NaT_months1_days1':
            dti = pd.DatetimeIndex(['2000-01-31', 'NaT'])
            res = dti + DateOffset(months=1, days=1)
            return ('value', res)
        if expr_id == 'scalar_max_months1_days-31':
            res = pd.Timestamp.max + DateOffset(months=1, days=-31)
            return ('value', res)
        raise ValueError('unknown expr_id')
    except Exception as e:
        return ('exception', type(e).__name__ + ': ' + str(e))

results = {}
for k in [
    'dti_max_months1_days-31',
    'dti_max_years1_days-366',
    'dti_max_months2_days-62',
    'dti_max_months1_hours-745',
    'dti_min_months-1_days32',
    'dti_max_months1_days-1',
    'dti_sec_unit_np_i64max',
    'dti_2000_01_31_NaT_months1_days1',
    'scalar_max_months1_days-31',
]:
    results[k] = apply_expr(k)

# record as structured values
from pandas._testing import assert_almost_equal

def fmt(x):
    kind, val = x
    if kind == 'exception':
        return val
    # val may be Timestamp/DatetimeIndex
    return str(val)

for k,v in results.items():
    probe(k, fmt(v))

